import {portView,vlanColor} from './port-view.js';
import {portConnection,compactProfile} from './port-status.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function renderPort(canvas,p,n,proxy,i,member,attached,alias){
 const side=i%2?'right-port':'left-port';
 if(member)return `<div data-anchor="${esc(p.id)}" class="port member-slot ${side}" title="Внутренняя привязка: ${esc(p.name)}"><span class="port-dot"></span><span class="port-caption">↳ ${esc(p.name)}</span></div>`;
 const view=portView(n,p),lagError=canvas.lag?.errors.get(p.id),status=portConnection(canvas.getState(),p,lagError),colors=view.vlans.map(vlanColor),bands=colors.map((c,i)=>`${c} ${i/colors.length*100}% ${(i+1)/colors.length*100}%`).join(',');
 const title=`${n.name} / ${view.name} · ${p.ip||'без IP'} · ${view.profile}\n${view.role} ${view.detail}${view.lag?'\n'+view.lag:''}\n${status.label}: ${status.description}${attached?'\nЭтот интерфейс принадлежит '+attached.host.name+', показан как порт моста '+attached.bridge.name:''}${proxy?'\nКонтакт свёрнутого объекта':''}`;
 const action=canvas.pending===p.id?'Отменить подключение':status.link?'Открыть свойства кабеля':'Начать подключение';
 const detail=view.detail||(p.ip?`${p.ip}/${p.prefix??24}`:p.tagged?`VLAN ${p.accessVlan||1} · с тегом`:'IP не задан');
 return `<button class="port ${p.kind==='physical'?'physical-port':'virtual-port'} ${side} ${status.link?'connected':''} port-${status.code} ${canvas.pending===p.id?'pending':''} ${view.role?'structured-port':''} ${lagError?'lag-warning':''}" data-anchor="${esc(p.id)}" data-port="${esc(p.id)}" ${alias?`data-alias="${esc(alias)}"`:''} data-vlans="${view.vlans.join(',')}" style="--vlan-color:${colors[0]||'#536b80'};--vlan-bands:linear-gradient(90deg,${bands||'#536b80,#536b80'})" title="${esc(title)}" aria-pressed="${canvas.pending===p.id}" aria-label="${esc(title.replaceAll('\n',' · ')+' · '+action)}"><span class="port-dot"></span><span class="port-caption"><span class="port-name"><strong class="port-label">${proxy?esc(n.name)+' / ':''}${esc(view.name)}</strong>${view.role?`<b class="port-role ${view.role.toLowerCase()}">${view.role}</b>`:''}</span><span class="port-technology"><i class="interface-kind">${p.kind==='physical'?'ФИЗ':'ВИРТ'}</i><span>${esc(compactProfile(p))}</span><small class="port-state">${status.label}</small></span><small class="port-meta">${esc(detail)}${p.ip&&view.detail&&!view.detail.includes(p.ip)?' · '+esc(p.ip):''}</small>${attached?`<small class="port-meta bridge-port-owner">Хост: ${esc(attached.host.name)}</small>`:''}${view.lag?`<small class="lag-badge">${esc(view.lag)}</small>`:''}</span></button>`;
}
